import {assertAssemblyEdit} from './native-assemblies.js';
import {hmAllowed} from './hm-rules.js';
import {sourceBlock} from './source-cells.js';
import{uid,inBounds}from'./model.js';
import{HMS,LEDGES}from'./field-defs.js';
import{automaticTileRule}from'./movement-defaults.js';
export{HMS,LEDGES};
export function fieldObjects(map,play=null){return(map.fieldObjects||[]).filter(o=>!play?.removedField?.has(o.id)&&!(o.permanent&&o.kind!=='strength'&&play?.quests?.has(o.completionFlag))).map(o=>({...o,...(o.permanent&&o.kind==='strength'&&play?.quests?.has(o.completionFlag)?o.solvedPosition:play?.fieldPositions?.get(o.id)||{})}));}
export function fieldAt(map,x,y,play=null){return fieldObjects(map,play).find(o=>o.x===x&&o.y===y);}
export function addFieldObject(map,kind,x,y,{assetId,access='standard',name,rom}={}){if(!['strength','rocksmash','cut'].includes(kind)||!inBounds(map,x,y))throw Error('Choose a boulder or tree inside the map.');assertAssemblyEdit(map,x,y);if(fieldAt(map,x,y))throw Error('This tile already has an HM object.');if((map.fieldObjects||[]).length>=64)throw Error('Keep one map under 64 field objects.');const o={id:uid(),kind,name:name||HMS[kind].name,x,y,assetId,access,...(rom?{rom}:{})};map.fieldObjects??=[];map.fieldObjects.push(o);return o;}
export function removeFieldObject(map,id){const o=map.fieldObjects?.find(o=>o.id===id);if(!o)return;if(o.rom?.type==='npc'){map.fieldRemovedNPCs??=[];if(!map.fieldRemovedNPCs.includes(o.rom.index))map.fieldRemovedNPCs.push(o.rom.index);}map.fieldObjects=map.fieldObjects.filter(o=>o.id!==id);for(const n of map.markers){if(!n.runtime?.steps)continue;n.runtime.steps=n.runtime.steps.filter(s=>!(s.type==='hm'&&s.targetId===id));if(!n.runtime.steps.length)delete n.runtime;}}
export function ledgeAt(map,x,y){if(!inBounds(map,x,y))return null;const r=map.movement?.[y*map.width+x],word=sourceBlock(map,x,y),b=r?.behavior??(r?.mode?.startsWith('ledge_')?LEDGES[r.mode.slice(6)]?.behavior:!r&&word!==undefined?(map.rom?.attributes?.[word&1023]??0)&0x1ff:null);return Object.entries(LEDGES).find(([,d])=>d.behavior===b)?.[0]||null;}
export function canUseHM(effect,play,access='standard',project=null){if(access!=='free'&&project?.hmRules?.moves?.[effect])return hmAllowed(project,effect,play);const h=HMS[effect];return access==='free'||!!h&&play?.hmMoves?.has(effect)&&play?.hmBadges?.has(h.badge);}
export function newFieldPreview(mapId,at={x:0,y:0}){return{...at,mapId,openGates:new Set(),removedField:new Set(),fieldPositions:new Map(),strength:false,flash:false,litMaps:new Set(),surfing:false,hmMoves:new Set(Object.keys(HMS)),hmBadges:new Set([1,2,3,4,5,6,7,8])};}
export function clearFieldPreview(play,nextMap=null){play.openGates.clear();play.removedField.clear();play.fieldPositions.clear();play.strength=false;play.surfing=false;if(!nextMap||!(nextMap.fieldSettings?.dark??nextMap.rom?.dark)){play.litMaps.clear();play.flash=false;}else if(play.flash)play.litMaps.add(nextMap.id);}
export function validateFields(project,assetIds){for(const m of project.maps){if(m.fieldObjects!==undefined&&(!Array.isArray(m.fieldObjects)||m.fieldObjects.length>64))throw Error('Invalid field object list.');const positions=new Set(),ids=new Set();for(const o of m.fieldObjects||[]){if(!o||typeof o.id!=='string'||ids.has(o.id)||!['strength','rocksmash','cut'].includes(o.kind)||!['standard','free'].includes(o.access)||!inBounds(m,o.x,o.y)||![o.x,o.y].every(Number.isInteger)||!assetIds.has(o.assetId))throw Error('A field object has invalid artwork, requirements or coordinates.');if(o.permanent&&(!o.completionFlag||!project.questFlags?.some(q=>q.id===o.completionFlag)))throw Error('A permanent HM object needs its project save flag.');if(o.permanent&&o.kind==='strength'&&(!o.solvedPosition||!inBounds(m,o.solvedPosition.x,o.solvedPosition.y)||![o.solvedPosition.x,o.solvedPosition.y].every(Number.isInteger)))throw Error('A permanent boulder needs a solved tile.');const key=o.x+','+o.y;if(positions.has(key))throw Error('Two field objects share one tile.');positions.add(key);ids.add(o.id);}if(m.fieldRemovedNPCs!==undefined&&(!Array.isArray(m.fieldRemovedNPCs)||m.fieldRemovedNPCs.some(i=>!Number.isInteger(i)||i<0||i>254)))throw Error('An original HM object removal is invalid.');if(m.fieldSettings&&typeof m.fieldSettings.dark!=='boolean')throw Error('Choose whether this map is dark.');}}

export function waterAt(map,x,y){if(!inBounds(map,x,y))return false;const rule=map.movement?.[y*map.width+x]||automaticTileRule(map,x,y);if(rule)return rule.mode==='water'||rule.behavior===0x10;const word=sourceBlock(map,x,y);if(word===undefined)return false;return ((map.rom?.attributes?.[word&1023]??0)&511)===0x10;}
